const slug=(h)=>h.trim().toLowerCase().replace(/[^\p{L}\p{N}\p{M}\s_-]/gu,'').replace(/\s/g,'-');
const anchorsOf=(file)=>{const seen={};const out=new Set();let inCode=false;
 for(const l of fs.readFileSync(file,'utf8').split(/\r?\n/)){if(/^```/.test(l)){inCode=!inCode;continue}if(inCode)continue;
  const m=l.match(/^#{1,6}\s+(.*)$/);if(!m)continue;let s=slug(m[1].replace(/`/g,''));
  if(seen[s]!=null){seen[s]++;s=`${s}-${seen[s]}`}else seen[s]=0;out.add(s);}return out;};
let bad=0;
for(const f of ['FEATURES.md','FEATURES.ko.md','FEATURES.de.md','FEATURES.ja.md']){
 const text=fs.readFileSync(dir+f,'utf8');
 for(const m of text.matchAll(/\]\(([^)\s]*)#([^)\s]+)\)/g)){
  const target=m[1]?path.join(dir,m[1]):dir+f;
  if(!fs.existsSync(target)){console.log(f,'missing file',m[1]);bad++;continue}
  const a=anchorsOf(target);const want=decodeURIComponent(m[2]);
  if(!a.has(want)){console.log(f,'BAD',m[1]||'(self)','#'+want);bad++}
 }
 for(const m of text.matchAll(/\]\(([^)#\s]+\.md)\)/g)){if(!m[1].startsWith('http')&&!fs.existsSync(path.join(dir,m[1]))){console.log(f,'missing link',m[1]);bad++}}
}
console.log('bad',bad);

