const fs=require('fs');
const dir='C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap/docs/';
const L={
 '':{ex:' One narrow exception: a `GetSqlQuery` that reads DD* repository metadata in the shape `stock-cbo` uses is auto-approved.',
   setup:'| Setup (`init`, `maintenance`) | `setup-init.mjs`, `setup-maintenance.mjs` | `claude --init-only` / `-p --init` creates the `.sc4sap` structure; the maintenance run does housekeeping |',
   chk:[', `stock-cbo` |',', `stock-cbo`, `cbo-relation-map`, `module-to-process` |']},
 '.ko':{ex:' 하나만 예외예요. `stock-cbo` 방식의 DD* 리포지토리 메타데이터를 읽는 `GetSqlQuery`는 자동 승인돼요.',
   setup:'| Setup (`init`, `maintenance`) | `setup-init.mjs`, `setup-maintenance.mjs` | `claude --init-only` / `-p --init` 실행 때 `.sc4sap` 구조를 만들어요. maintenance 실행 때 정리 작업을 해요 |',
   chk:['`stock-cbo`에서 써요 |','`stock-cbo`, `cbo-relation-map`, `module-to-process`에서 써요 |']},
 '.de':{ex:' Eine enge Ausnahme: ein `GetSqlQuery`, das DD*-Repository-Metadaten in der Form von `stock-cbo` liest, wird automatisch genehmigt.',
   setup:'| Setup (`init`, `maintenance`) | `setup-init.mjs`, `setup-maintenance.mjs` | `claude --init-only` / `-p --init` legt die `.sc4sap`-Struktur an; der Wartungslauf räumt auf |',
   chk:['`compare-programs` und `stock-cbo` verwendet |','`compare-programs`, `stock-cbo`, `cbo-relation-map` und `module-to-process` verwendet |']},
 '.ja':{ex:' 唯一の例外として、`stock-cbo` と同じ形で DD* リポジトリメタデータを読む `GetSqlQuery` は自動承認されます。',
   setup:'| Setup（`init`、`maintenance`） | `setup-init.mjs`、`setup-maintenance.mjs` | `claude --init-only` / `-p --init` の実行時に `.sc4sap` の構成を作成し、maintenance の実行時に整理を行います |',
   chk:['`stock-cbo` が使います |','`stock-cbo`、`cbo-relation-map`、`module-to-process` が使います |']},
};
for(const [k,v] of Object.entries(L)){
 const f=dir+`FEATURES${k}.md`;let s=fs.readFileSync(f,'utf8');const crlf=s.includes('\r\n');let lines=s.replace(/\r\n/g,'\n').split('\n');
 const pi=lines.findIndex(l=>l.includes('`permission-approver.mjs`'));
 const si=lines.findIndex(l=>l.startsWith('| SessionStart |'));
 if(pi<0||si<0){console.error(k,'rows missing');process.exit(1)}
 lines[pi]=lines[pi].replace(/\s*\|\s*$/,v.ex+' |');
 lines.splice(si+1,0,v.setup);
 let t=lines.join('\n');
 if(!t.includes(v.chk[0])){console.error(k,'checker MISS');process.exit(1)}
 t=t.replace(v.chk[0],v.chk[1]);
 fs.writeFileSync(f,crlf?t.replace(/\n/g,'\r\n'):t);console.log(k||'en','ok');
}

